// #3608cf — общие проверки «таблица не растягивает страницу на 390 px». Только чтение.
// .table-wrap — класс контейнера из самого исправления тикета (position:relative на .table-wrap), поэтому проверяем по нему.
import * as path from 'path';
import { Page, Locator, expect } from '@playwright/test';

export const MOBILE_VIEWPORT = { width: 390, height: 844 };
export const authFile = (id: 'admin' | 'platform') => path.resolve(__dirname, '../../../auth', `${id}.json`);

export const dialog = (page: Page) => page.getByRole('dialog').or(page.getByRole('alertdialog'));
export const tableWraps = (page: Page) => page.locator('.table-wrap');

/** Страница ровно по ширине экрана и не сдвинута: scrollWidth == innerWidth, scrollX == 0. */
export async function expectPageFits(page: Page, what: string) {
  await expect
    .poll(() => page.evaluate(() => ({ iw: window.innerWidth, sw: document.documentElement.scrollWidth, sx: window.scrollX })), { message: what })
    .toEqual({ iw: MOBILE_VIEWPORT.width, sw: MOBILE_VIEWPORT.width, sx: 0 });
}

/** Таблица шире контейнера (прокрутка внутри него), а первая колонка видна без прокрутки (RTL: scrollLeft 0). */
export async function expectScrollsInsideWrap(wrap: Locator, what: string) {
  const m = await wrap.evaluate((el) => {
    const w = el.getBoundingClientRect();
    const th = el.querySelector('th')!.getBoundingClientRect();
    return { cw: el.clientWidth, sw: el.scrollWidth, sl: Math.round(el.scrollLeft), wl: w.left, wr: w.right, thl: th.left, thr: th.right };
  });
  expect(m.sw, `${what}: таблица шире контейнера (прокрутка внутри него)`).toBeGreaterThan(m.cw);
  expect(m.sl, `${what}: начальная прокрутка 0`).toBe(0);
  expect(m.thr, `${what}: первая колонка видна справа (RTL)`).toBeLessThanOrEqual(m.wr + 1);
  expect(m.thl, `${what}: первая колонка видна слева`).toBeGreaterThanOrEqual(m.wl - 1);
}

/** Кнопка достижима: прокрутка только внутри .table-wrap, кнопка внутри контейнера и в экране, нажатие попадёт в неё, страница не сдвинулась. */
export async function expectReachable(page: Page, btn: Locator, what: string) {
  await expect(btn, what).toBeVisible();
  await btn.evaluate((el) => el.scrollIntoView({ block: 'nearest', inline: 'nearest' }));
  const r = await btn.evaluate((el) => {
    const b = el.getBoundingClientRect();
    const w = el.closest('.table-wrap')!.getBoundingClientRect();
    const top = document.elementFromPoint(b.left + b.width / 2, b.top + b.height / 2);
    return {
      inWrap: b.left >= w.left - 1 && b.right <= w.right + 1,
      inViewport: b.left >= 0 && b.right <= window.innerWidth,
      hit: top === el || el.contains(top),
    };
  });
  expect(r, `${what}: достижима внутри контейнера`).toEqual({ inWrap: true, inViewport: true, hit: true });
  await expectPageFits(page, `${what}: после прокрутки к кнопке`);
}

/** Открытое окно целиком в экране, страница не шире 390. */
export async function expectDialogFits(page: Page, what: string) {
  const dlg = dialog(page).first();
  await expect(dlg, what).toBeVisible();
  const b = await dlg.evaluate((el) => {
    const r = el.getBoundingClientRect();
    return { l: r.left, r: r.right, t: r.top, b: r.bottom, iw: window.innerWidth, ih: window.innerHeight };
  });
  expect(b.l, `${what}: левый край`).toBeGreaterThanOrEqual(0);
  expect(b.r, `${what}: правый край`).toBeLessThanOrEqual(b.iw);
  expect(b.t, `${what}: верх`).toBeGreaterThanOrEqual(0);
  expect(b.b, `${what}: низ`).toBeLessThanOrEqual(b.ih);
  await expectPageFits(page, `${what}: страница`);
}

/** Закрыть окно через «ביטול» (ничего не сохраняем и не подтверждаем). */
export async function cancelDialog(page: Page) {
  await dialog(page).first().getByRole('button', { name: 'ביטול', exact: true }).click();
  await expect(dialog(page)).toHaveCount(0);
}
